   // 初始化 Quill 编辑器
   const quillOptions = {
       theme: 'snow',
       modules: {
           toolbar: [
               ['bold', 'italic', 'underline'],
               [{ 'list': 'ordered'}, { 'list': 'bullet' }],
               ['link', 'clean']
           ]
       },
       placeholder: '在此输入内容...'
   };

   const quillFullDesc = new Quill('#toolFullDescEditor', quillOptions);
   const quillFeatures = new Quill('#toolFeaturesEditor', quillOptions);
   const quillHowToUse = new Quill('#toolHowToUseEditor', quillOptions);

   const form = document.getElementById('cooperationForm');
   const message = document.getElementById('message');
   const submitBtn = document.getElementById('submitBtn');

   form.addEventListener('submit', async (e) => {
       e.preventDefault();

       const name = document.getElementById('name').value.trim();
       const email = document.getElementById('email').value.trim();
       const phone = document.getElementById('phone').value.trim();
       const content = document.getElementById('content').value.trim();

       // 如果工具区展开，则验证必填
       const isToolSectionOpen = document.getElementById('toolFormSection').classList.contains('show');

       let uploadedImageUrl = document.getElementById('toolPreviewUrl').value;
       let fileInput = document.getElementById('toolImageFile');

       // 验证邮箱和电话至少填一个
       if (!email && !phone) {
           showMessage('邮箱和电话至少需要填写一个 / Please provide at least one contact method (email or phone)', 'error');
           return;
       }

       // 验证必填项
       if (!name) {
           showMessage('请输入姓名 / Please enter your name', 'error');
           return;
       }

       if (!content) {
           showMessage('请输入合作内容 / Please enter partnership details', 'error');
           return;
       }

       if (isToolSectionOpen) {
           if (!document.getElementById('toolName').value.trim() || 
               !document.getElementById('toolShortDesc').value.trim() || 
               !document.getElementById('toolWebsite').value.trim()) {
               showMessage('请填写完整的工具常规必填信息（工具名称、一行简介、官网） / Please fill in the required tool information (Tool Name, Short Description, Website URL)', 'error');
               return;
           }
       }

       submitBtn.disabled = true;
       submitBtn.textContent = '提交中... / Submitting...';
       hideMessage();

       try {
           // 如果用户选择了文件但还没上传完成（这里在提交时直接处理上传）
           if (isToolSectionOpen && fileInput.files.length > 0 && !uploadedImageUrl) {
               submitBtn.textContent = '正在上传图片... / Uploading image...';
               const formData = new FormData();
               formData.append('file', fileInput.files[0]);

               const uploadData = await window.API.upload('/upload/public', formData);
               uploadedImageUrl = uploadData.url;
               document.getElementById('toolPreviewUrl').value = uploadedImageUrl;
           }

           let toolPayload = null;
           if (isToolSectionOpen && document.getElementById('toolName').value.trim()) {
               // 检查富文本是否为空 (Quill 默认会有 <p><br></p>)
               const getQuillContent = (quill) => {
                   const html = quill.root.innerHTML;
                   if (html === '<p><br></p>') return "";
                   return html;
               };

               toolPayload = {
                   name: document.getElementById('toolName').value.trim(),
                   shortDescription: document.getElementById('toolShortDesc').value.trim(),
                   websiteUrl: document.getElementById('toolWebsite').value.trim(),
                   fullDescription: getQuillContent(quillFullDesc),
                   keyFeatures: getQuillContent(quillFeatures),
                   howToUse: getQuillContent(quillHowToUse),
                   pricingModel: document.getElementById('toolPricingModel').value,
                   categoryId: document.getElementById('toolCategory').value ? parseInt(document.getElementById('toolCategory').value) : null,
                   pricingDetails: document.getElementById('toolPricingDetails').value.trim(),
                   previewImageUrl: uploadedImageUrl || ""
               };
           }

           submitBtn.textContent = '正在提交... / Submitting...';

           // 使用 API 封装
           await window.API.Cooperation.submit({
               name,
               email: email || null,
               phone: phone || null,
               content,
               tool: toolPayload
           });

           // 显示成功提示
           showSuccessMessage();
           form.reset();
       } catch (error) {
           console.error('Submit error:', error);
           showMessage((error.message || '提交失败，请检查网络连接') + ' / Submission failed, please check your network connection', 'error');
           submitBtn.disabled = false;
           submitBtn.textContent = '提交申请 / Submit Application';
       }
   });

   function showMessage(text, type, isHtml = false) {
       if (isHtml) {
           message.innerHTML = text;
       } else {
           message.innerHTML = `<span>${escapeHtml(text)}</span>`;
       }
       message.className = `message ${type} show`;

       // 自动滚动到消息区域，确保用户看到提示
       message.scrollIntoView({ behavior: 'smooth', block: 'center' });
   }

   function escapeHtml(text) {
       const div = document.createElement('div');
       div.textContent = text;
       return div.innerHTML;
   }

   function showSuccessMessage() {
       let countdown = 3;
       const updateMessage = () => {
           if (countdown > 0) {
               const html = `<span>提交成功！我们会尽快与您联系。 / Submission successful! We will contact you soon.<br><span class="message-countdown">${countdown}秒后自动返回首页... / Returning to home page in ${countdown}s...</span></span>`;
               showMessage(html, 'success', true);
               countdown--;
               setTimeout(updateMessage, 1000);
           } else {
               window.location.href = 'index.html';
           }
       };
       updateMessage();
   }

   function hideMessage() {
       message.classList.remove('show');
   }

   // --- 新增工具展示面板逻辑 ---
   document.getElementById('toolToggleBtn').addEventListener('click', function() {
       this.classList.toggle('open');
       document.getElementById('toolFormSection').classList.toggle('show');
       if (this.classList.contains('open')) {
           loadCategories();
       }
   });

   document.getElementById('toolImageFile').addEventListener('change', function(e) {
       const file = e.target.files[0];
       if (file) {
           if (file.size > 2 * 1024 * 1024) {
               alert('图片必须小于 2MB / Image must be smaller than 2MB');
               this.value = '';
               return;
           }
           const reader = new FileReader();
           reader.onload = function(e) {
               const preview = document.getElementById('imagePreview');
               preview.src = e.target.result;
               preview.style.display = 'block';
           };
           reader.readAsDataURL(file);
           // 重置 url，以便在 submit 时触发新的上传
           document.getElementById('toolPreviewUrl').value = '';
       }
   });

   let categoriesLoaded = false;
   async function loadCategories() {
       if (categoriesLoaded) return;
       try {
           const res = await window.API.Home.getCategories();
           const sel = document.getElementById('toolCategory');
           sel.innerHTML = '<option value="">--请选择领域 / Please select category--</option>';
           const categories = Array.isArray(res) ? res : (res.data || []);

           const topCats = categories.filter(c => !c.parentId || c.parentId === 0);
           const usedIds = new Set();

           topCats.forEach(top => {
               const opt = document.createElement('option');
               opt.value = top.id;
               opt.textContent = `[ ${top.name} ]`;
               // 改变首层选项的样式展示
               opt.style.fontWeight = 'bold';
               sel.appendChild(opt);
               usedIds.add(top.id);

               const children = categories.filter(c => c.parentId === top.id);
               children.forEach(child => {
                   const childOpt = document.createElement('option');
                   childOpt.value = child.id;
                   childOpt.textContent = `  ├─ ${child.name}`;
                   sel.appendChild(childOpt);
                   usedIds.add(child.id);
               });
           });

           // 将未匹配到的（可能是三级或脏数据）作为额外项补齐
           categories.forEach(cat => {
               if (!usedIds.has(cat.id)) {
                   const opt = document.createElement('option');
                   opt.value = cat.id;
                   opt.textContent = cat.name;
                   sel.appendChild(opt);
               }
           });
           categoriesLoaded = true;
       } catch (err) {
           console.error("无法加载分类列表:", err);
       }
   }











